using AITaskAgent.LLM.Constants;

namespace AITaskAgent.LLM.Models;

/// <summary>
/// Result of an LLM generation request, encapsulating one or more candidates and execution metadata.
/// Implements the Result pattern for provider-level errors.
/// </summary>
public sealed class LlmResult
{
    /// <summary>All candidates generated by the model.</summary>
    public IReadOnlyList<LlmResponse> Candidates { get; init; } = [];

    /// <summary>Total tokens used (prompt + completion).</summary>
    public int? TokensUsed { get; init; }

    /// <summary>Prompt tokens used.</summary>
    public int? PromptTokens { get; init; }

    /// <summary>Completion tokens generated.</summary>
    public int? CompletionTokens { get; init; }

    /// <summary>
    /// Estimated cost in USD. Settable within the assembly because services report tokens but
    /// cannot price them - they never see the provider's model catalogue - so BaseLlmStep fills
    /// it in from <c>LlmProvider.CalculateCost</c> once the call returns.
    /// </summary>
    public decimal? CostUsd { get; internal set; }

    /// <summary>Model used for generation.</summary>
    public string? Model { get; init; }

    /// <summary>Native provider-specific response object for advanced scenarios.</summary>
    public object? NativeResponse { get; init; }

    /// <summary>Provider exception if the request failed.</summary>
    public Exception? Error { get; init; }

    /// <summary>Indicates if the error is transient and should be retried.</summary>
    public bool IsRetriable { get; init; }

    /// <summary>Convenience property to get the content of the first candidate.</summary>
    public string Content => Candidates.Count > 0 ? Candidates[0].Content : string.Empty;

    /// <summary>Convenience property to get the reasoning of the first candidate.</summary>
    public string? Reasoning => Candidates.Count > 0 ? Candidates[0].Reasoning : null;

    /// <summary>True if the request completed without provider errors.</summary>
    public bool IsSuccess => Error == null;

    /// <summary>The reason the generation stopped.</summary>
    public FinishReason? FinishReason => Candidates.Count > 0 ? Candidates[0].FinishReason : null;

    /// <summary>Factory for successful results.</summary>
    public static LlmResult Success(IReadOnlyList<LlmResponse> candidates, int? tokensUsed = null, int? promptTokens = null, int? completionTokens = null, decimal? costUsd = null, string? model = null, object? nativeResponse = null) =>
        new()
        {
            Candidates = candidates,
            TokensUsed = tokensUsed,
            PromptTokens = promptTokens,
            CompletionTokens = completionTokens,
            CostUsd = costUsd,
            Model = model,
            NativeResponse = nativeResponse
        };

    /// <summary>Factory for failed results.</summary>
    public static LlmResult Failure(Exception error, bool isRetriable) =>
        new()
        {
            Error = error,
            IsRetriable = isRetriable
        };
}
